// ValidateRole implements mm_postgres.RWUsers
func (mmValidateRole *UserMock) ValidateRole(ctx context.Context, role string) (err error) {
	mm_atomic.AddUint64(&mmValidateRole.beforeValidateRoleCounter, 1)
	defer mm_atomic.AddUint64(&mmValidateRole.afterValidateRoleCounter, 1)

	mmValidateRole.t.Helper()

	if mmValidateRole.inspectFuncValidateRole != nil {
		mmValidateRole.inspectFuncValidateRole(ctx, role)
	}

	mm_params := UserMockValidateRoleParams{ctx, role}

	// Record call args
	mmValidateRole.ValidateRoleMock.mutex.Lock()
	mmValidateRole.ValidateRoleMock.callArgs = append(mmValidateRole.ValidateRoleMock.callArgs, &mm_params)
	mmValidateRole.ValidateRoleMock.mutex.Unlock()

	for _, e := range mmValidateRole.ValidateRoleMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmValidateRole.ValidateRoleMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmValidateRole.ValidateRoleMock.defaultExpectation.Counter, 1)
		mm_want := mmValidateRole.ValidateRoleMock.defaultExpectation.params
		mm_want_ptrs := mmValidateRole.ValidateRoleMock.defaultExpectation.paramPtrs

		mm_got := UserMockValidateRoleParams{ctx, role}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmValidateRole.t.Errorf("UserMock.ValidateRole got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmValidateRole.ValidateRoleMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.role != nil && !minimock.Equal(*mm_want_ptrs.role, mm_got.role) {
				mmValidateRole.t.Errorf("UserMock.ValidateRole got unexpected parameter role, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmValidateRole.ValidateRoleMock.defaultExpectation.expectationOrigins.originRole, *mm_want_ptrs.role, mm_got.role, minimock.Diff(*mm_want_ptrs.role, mm_got.role))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmValidateRole.t.Errorf("UserMock.ValidateRole got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmValidateRole.ValidateRoleMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmValidateRole.ValidateRoleMock.defaultExpectation.results
		if mm_results == nil {
			mmValidateRole.t.Fatal("No results are set for the UserMock.ValidateRole")
		}
		return (*mm_results).err
	}
	if mmValidateRole.funcValidateRole != nil {
		return mmValidateRole.funcValidateRole(ctx, role)
	}
	mmValidateRole.t.Fatalf("Unexpected call to UserMock.ValidateRole. %v %v", ctx, role)
	return
}

