// MinimockValidateRoleInspect logs each unmet expectation
func (m *UserMock) MinimockValidateRoleInspect() {
	for _, e := range m.ValidateRoleMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to UserMock.ValidateRole at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterValidateRoleCounter := mm_atomic.LoadUint64(&m.afterValidateRoleCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ValidateRoleMock.defaultExpectation != nil && afterValidateRoleCounter < 1 {
		if m.ValidateRoleMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to UserMock.ValidateRole at\n%s", m.ValidateRoleMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to UserMock.ValidateRole at\n%s with params: %#v", m.ValidateRoleMock.defaultExpectation.expectationOrigins.origin, *m.ValidateRoleMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcValidateRole != nil && afterValidateRoleCounter < 1 {
		m.t.Errorf("Expected call to UserMock.ValidateRole at\n%s", m.funcValidateRoleOrigin)
	}

	if !m.ValidateRoleMock.invocationsDone() && afterValidateRoleCounter > 0 {
		m.t.Errorf("Expected %d calls to UserMock.ValidateRole at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ValidateRoleMock.expectedInvocations), m.ValidateRoleMock.expectedInvocationsOrigin, afterValidateRoleCounter)
	}
}

